using Microsoft.AspNetCore.Identity;
using Microsoft.Data.Sqlite;
using Microsoft.Extensions.Options;
using System.Security.Cryptography;
using System.Text;
using System.Text.RegularExpressions;
namespace HomeLibrary;
public sealed record AccountRegistration(string Username,string Password,string Name,string Contact,string ShareToken,string ChallengeToken="");
public sealed record AccountLogin(string Username,string Password);
public sealed record AccountReset(string Token,string Password);
public sealed record AccountApproval(string AccountId,string ReaderId="",string BorrowerId="",bool RestoreBorrower=false,bool CreateBorrower=false);
public sealed record BorrowerAccount(string Id,string Username,string Name,string Contact,string Status,string ReaderId,string BorrowerId);
// Separate credential store: no password hashes or sessions enter catalog JSON,
// library exports or paired-phone snapshots. Approval alone binds existing history.
public sealed class BorrowerAccounts:IDisposable {
 readonly object gate=new();readonly SqliteConnection db;readonly PasswordHasher<string> hasher=new(Options.Create(new PasswordHasherOptions{IterationCount=210000}));readonly string dummy;
 public BorrowerAccounts(string directory){db=new SqliteConnection(new SqliteConnectionStringBuilder{DataSource=Path.Combine(directory,"borrower-accounts.sqlite")}.ToString());db.Open();Run("PRAGMA journal_mode=WAL; PRAGMA secure_delete=ON; PRAGMA synchronous=FULL; CREATE TABLE IF NOT EXISTS accounts(id TEXT PRIMARY KEY,username TEXT NOT NULL UNIQUE,name TEXT NOT NULL,contact TEXT NOT NULL,password TEXT NOT NULL,status TEXT NOT NULL,reader TEXT NOT NULL DEFAULT '',borrower TEXT NOT NULL DEFAULT '',failures INTEGER NOT NULL DEFAULT 0,locked INTEGER NOT NULL DEFAULT 0,reset TEXT NOT NULL DEFAULT '',reset_expires INTEGER NOT NULL DEFAULT 0); CREATE TABLE IF NOT EXISTS vault_deletions(account TEXT PRIMARY KEY); CREATE TABLE IF NOT EXISTS reading_owners(reader TEXT PRIMARY KEY,account TEXT NOT NULL); INSERT OR IGNORE INTO reading_owners(reader,account) SELECT reader,id FROM accounts WHERE reader!=''; CREATE TABLE IF NOT EXISTS sessions(hash TEXT PRIMARY KEY,account TEXT NOT NULL,expires INTEGER NOT NULL);");Run("CREATE TABLE IF NOT EXISTS privacy_meta(version INTEGER PRIMARY KEY); UPDATE accounts SET reset='',reset_expires=0 WHERE NOT EXISTS(SELECT 1 FROM privacy_meta WHERE version=1); DELETE FROM sessions WHERE NOT EXISTS(SELECT 1 FROM privacy_meta WHERE version=1); INSERT OR IGNORE INTO privacy_meta VALUES(1);");dummy=hasher.HashPassword("dummy","Timing-only-password-never-used-for-login");}
 SqliteCommand Command(string sql,params (string,object)[] args){var c=db.CreateCommand();c.CommandText=sql;foreach(var (name,value) in args)c.Parameters.AddWithValue(name,value);return c;}
 void Run(string sql,params (string,object)[] args){using var c=Command(sql,args);c.ExecuteNonQuery();}
 static long Now=>DateTimeOffset.UtcNow.ToUnixTimeSeconds();
 static string Digest(string token)=>Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(token)));
 static string Token()=>Convert.ToBase64String(RandomNumberGenerator.GetBytes(32)).TrimEnd('=').Replace('+','-').Replace('/','_');
 static string Username(string? value)=>(value??"").Trim().ToLowerInvariant();
 static void Password(string? value){if(value==null||value.Length<12||value.Length>128)throw new LibraryError("Use a password or passphrase of 12–128 characters.");}
 BorrowerAccount Read(SqliteDataReader r)=>new(r.GetString(0),r.GetString(1),r.GetString(2),r.GetString(3),r.GetString(4),r.GetString(5),r.GetString(6));
 public List<BorrowerAccount> List(){lock(gate){using var c=Command("SELECT id,username,name,contact,status,reader,borrower FROM accounts ORDER BY status DESC,name");using var r=c.ExecuteReader();var result=new List<BorrowerAccount>();while(r.Read())result.Add(Read(r));return result;}}
 public BorrowerAccount Get(string id)=>List().Find(x=>x.Id==id)??throw new LibraryError("Account not found.",404);
 public BorrowerAccount Register(AccountRegistration input){lock(gate){var username=Username(input.Username);if(!Regex.IsMatch(username,@"^[a-z0-9][a-z0-9_.-]{2,39}$"))throw new LibraryError("Choose a username of 3–40 letters, numbers, dots, underscores or hyphens.");Password(input.Password);var name=(input.Name??"").Trim();var contact=(input.Contact??"").Trim();if(name.Length is <1 or >80||name.Any(char.IsControl))throw new LibraryError("Enter your name (up to 80 characters).");if(contact.Length>200||contact!=""&&BookRequests.ContactKey(contact)=="")throw new LibraryError("Enter one phone number or email, or leave contact blank.");if(List().Count(x=>x.Status=="pending")>=100)throw new LibraryError("Sign-up is temporarily full. Please contact the librarian.",503);var id=Guid.NewGuid().ToString("N");try{Run("INSERT INTO accounts(id,username,name,contact,password,status) VALUES($id,$user,$name,$contact,$password,'pending')",("$id",id),("$user",username),("$name",name),("$contact",contact),("$password",hasher.HashPassword(id,input.Password)));}catch(SqliteException e)when(e.SqliteErrorCode==19){throw new LibraryError("That username is unavailable. Choose another or sign in.");}return Get(id);}}
 public string Session(string accountId){lock(gate){Run("DELETE FROM sessions WHERE expires<$now",("$now",Now));var token=Token();Run("INSERT INTO sessions VALUES($hash,$account,$expires)",("$hash",Digest(token)),("$account",accountId),("$expires",Now+86400));return token;}}
 public string Login(AccountLogin input){lock(gate){var user=Username(input.Username);string id="",hash=dummy,status="";long locked=0;int failures=0;
  using(var c=Command("SELECT id,password,status,failures,locked FROM accounts WHERE username=$user",("$user",user)))using(var r=c.ExecuteReader()){if(r.Read()){id=r.GetString(0);hash=r.GetString(1);status=r.GetString(2);failures=r.GetInt32(3);locked=r.GetInt64(4);}}
  var password=input.Password??"";var valid=password.Length<=128&&hasher.VerifyHashedPassword(id,hash,password)!=PasswordVerificationResult.Failed;
  if(id==""||!valid||locked>Now||status=="blocked"){
   if(id!=""&&locked<=Now){var count=locked!=0?1:failures+1;Run("UPDATE accounts SET failures=$n,locked=$locked WHERE id=$id",("$n",count),("$locked",count>=5?Now+900:0),("$id",id));}
   throw new LibraryError("Sign-in failed. Check your username/password or try later. Contact the librarian if your account is blocked.",401);
  }
  Run("UPDATE accounts SET failures=0,locked=0 WHERE id=$id",("$id",id));return Session(id);
 }}
 public BorrowerAccount? Resolve(string token){lock(gate){if(token.Length!=43)return null;using var c=Command("SELECT a.id,a.username,a.name,a.contact,a.status,a.reader,a.borrower FROM sessions s JOIN accounts a ON a.id=s.account WHERE s.hash=$hash AND s.expires>$now AND a.status!='blocked'",("$hash",Digest(token)),("$now",Now));using var r=c.ExecuteReader();return r.Read()?Read(r):null;}}
 public void Logout(string token){lock(gate)Run("DELETE FROM sessions WHERE hash=$hash",("$hash",Digest(token)));}
 public BorrowerAccount Approve(AccountApproval input,Store store){lock(gate){var a=Get(input.AccountId);if(input.ReaderId==""){using var owned=Command("SELECT reader FROM reading_owners WHERE account=$id",("$id",a.Id));var oldReader=owned.ExecuteScalar()?.ToString();if(oldReader!=null&&store.Read().State.Readers.Find(r=>r.Id==oldReader) is {} priorReader){var needsReplacement=input.BorrowerId==""&&!input.RestoreBorrower&&!store.Read().State.Borrowers.Any(b=>b.Id==priorReader.BorrowerId&&!b.Archived);input=input with{ReaderId=oldReader,CreateBorrower=input.CreateBorrower||needsReplacement};}}if(a.Status=="active")throw new LibraryError("This account is already approved. Block it before changing its access.");if(List().Any(x=>x.Id!=a.Id&&x.ReaderId==input.ReaderId&&input.ReaderId!=""))throw new LibraryError("This reading profile already belongs to an account.");if(input.ReaderId!=""){using var owner=Command("SELECT account FROM reading_owners WHERE reader=$reader",("$reader",input.ReaderId));var owned=owner.ExecuteScalar()?.ToString();if(owned!=null&&owned!=a.Id)throw new LibraryError("This private reading profile cannot be assigned to another account.",403);}
 if(input.BorrowerId!=""&&List().Any(x=>x.Id!=a.Id&&x.BorrowerId==input.BorrowerId))throw new LibraryError("This borrower is already linked to another account.");
 var fresh=false;if(input.ReaderId==""&&input.BorrowerId!=""){if(List().Any(x=>x.Id!=a.Id&&x.BorrowerId==input.BorrowerId))throw new LibraryError("This borrower is already linked to another account.");foreach(var prior in store.Read().State.Readers.Where(r=>r.BorrowerId==input.BorrowerId)){using var owner=Command("SELECT account FROM reading_owners WHERE reader=$id",("$id",prior.Id));var id=owner.ExecuteScalar()?.ToString();if(id!=null&&id!=a.Id)fresh=true;}}
 var reader=store.AccountReader(a.Name,a.Contact,input.ReaderId,input.BorrowerId,input.RestoreBorrower,input.CreateBorrower,fresh);if(List().Any(x=>x.Id!=a.Id&&x.ReaderId==reader.Id))throw new LibraryError("This reading profile already belongs to an account.");using(var owner=Command("SELECT account FROM reading_owners WHERE reader=$reader",("$reader",reader.Id))){var owned=owner.ExecuteScalar()?.ToString();if(owned!=null&&owned!=a.Id)throw new LibraryError("This private reading profile cannot be assigned to another account.",403);}
 Run("INSERT OR IGNORE INTO reading_owners VALUES($reader,$account)",("$reader",reader.Id),("$account",a.Id));Run("UPDATE accounts SET status='active',reader=$reader,borrower=$borrower,failures=0,locked=0,reset='',reset_expires=0 WHERE id=$id",("$reader",reader.Id),("$borrower",reader.BorrowerId),("$id",a.Id));return Get(a.Id);}}
 public BorrowerAccount Unblock(string id){lock(gate){var a=Get(id);if(a.Status!="blocked")throw new LibraryError("Only blocked accounts can be unblocked.");Run("UPDATE accounts SET status='pending',reader='',borrower='',failures=0,locked=0,reset='',reset_expires=0 WHERE id=$id",("$id",id));Run("DELETE FROM sessions WHERE account=$id",("$id",id));return Get(id);}}
 public void Block(string id){lock(gate){Get(id);Run("UPDATE accounts SET status='blocked',reset='',reset_expires=0 WHERE id=$id",("$id",id));Run("DELETE FROM sessions WHERE account=$id",("$id",id));}}
 public object Delete(AccountDeletionInput input,Store store,ReadingAccess access,Reminders reminders){lock(gate){
  var account=Get(input.AccountId);
  var (plan,warnings)=store.EraseAccountInformation(account,input,List(),p=>{Block(account.Id);foreach(var id in p.ReaderIds.Append(account.ReaderId).Where(id=>id!="").Distinct())access.Change(id,"disable");});
  if(!input.DeleteInformation&&account.ReaderId!="")store.EraseLegacyReading(account.ReaderId);
  Run("BEGIN IMMEDIATE");try{Run("INSERT OR IGNORE INTO vault_deletions VALUES($id)",("$id",account.Id));Run("DELETE FROM sessions WHERE account=$id;DELETE FROM accounts WHERE id=$id",("$id",account.Id));if(input.DeleteInformation)foreach(var reader in plan.ReaderIds)Run("DELETE FROM reading_owners WHERE reader=$reader",("$reader",reader));Run("COMMIT");}catch{Run("ROLLBACK");throw;}
  var notices=warnings.ToList();try{reminders.EraseDeliveries(plan.LoanIds);}catch(SqliteException){notices.Add("Reminder delivery metadata could not be completely removed. Review the private reminder database.");}try{Run("PRAGMA wal_checkpoint(TRUNCATE);VACUUM;PRAGMA wal_checkpoint(TRUNCATE);");}catch(SqliteException){notices.Add("Account database compaction could not finish; the sign-in account was deleted.");}
  return new{deleted=true,informationDeleted=input.DeleteInformation,warnings=notices,snapshot=store.AdminRead()};
 }}
 public string[] PendingVaultDeletes(){lock(gate){using var c=Command("SELECT account FROM vault_deletions");using var rows=c.ExecuteReader();var ids=new List<string>();while(rows.Read())ids.Add(rows.GetString(0));return ids.ToArray();}}
 public void CompleteVaultDelete(string id){lock(gate)Run("DELETE FROM vault_deletions WHERE account=$id",("$id",id));}
 public object WithActiveAccount(string id,Store store,Func<BorrowerAccount,object> action){lock(gate){var a=Get(id);ApprovedReader(a,store);return action(a);}}
 public void VerifyPassword(string id,string password){lock(gate){var account=Get(id);var token=Login(new(account.Username,password));Logout(token);}}
 public string ResetLink(string id,string origin){lock(gate){var a=Get(id);if(a.Status=="blocked")throw new LibraryError("Approve the account before issuing a reset link.");var token=Token();Run("UPDATE accounts SET reset=$reset,reset_expires=$expires WHERE id=$id",("$reset",Digest(token)),("$expires",Now+1800),("$id",id));return origin.TrimEnd('/')+"/account/#reset="+token;}}
 public void Reset(AccountReset input){lock(gate){Password(input.Password);if(input.Token==null||input.Token.Length!=43)throw new LibraryError("This reset link is invalid or expired.",401);string id="";using(var c=Command("SELECT id FROM accounts WHERE reset=$reset AND reset_expires>$now AND status!='blocked'",("$reset",Digest(input.Token)),("$now",Now)))using(var r=c.ExecuteReader()){if(r.Read())id=r.GetString(0);}if(id=="")throw new LibraryError("This reset link is invalid or expired.",401);Run("UPDATE accounts SET password=$password,reset='',reset_expires=0,failures=0,locked=0 WHERE id=$id",("$password",hasher.HashPassword(id,input.Password)),("$id",id));Run("DELETE FROM sessions WHERE account=$id",("$id",id));}}
 public static string ApprovedReader(BorrowerAccount account,Store store){var s=store.Read().State;var reader=s.Readers.Find(r=>r.Id==account.ReaderId);if(account.Status!="active"||reader==null||reader.BorrowerId!=account.BorrowerId||!s.Borrowers.Any(b=>b.Id==account.BorrowerId&&!b.Archived))throw new LibraryError("Your account needs librarian approval or relinking before personal history is available.",403);return reader.Id;}
 public void Dispose(){lock(gate)db.Dispose();}
}
